-- Initial schema foundation. Test RLS and add transactional server operations before production.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,created_at timestamptz not null default now());
create table public.user_roles(user_id uuid primary key references auth.users(id) on delete cascade,role text not null check(role in ('owner','catalogue_manager','inventory_manager','fulfilment','support','finance','marketing')));
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,active boolean not null default true,display_order int not null default 0);
create table public.products(id uuid primary key default gen_random_uuid(),category_id uuid not null references public.categories(id),name text not null,slug text unique not null,sku text unique not null,description text not null default '',status text not null default 'draft' check(status in ('draft','active','archived')),attributes jsonb not null default '{}',created_at timestamptz not null default now());
create table public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id),sku text unique not null,variant_name text not null default 'Default',unit_label text not null default 'each',price numeric(12,2) not null check(price>=0),mrp numeric(12,2) not null check(mrp>=price),stock_quantity integer not null default 0 check(stock_quantity>=0),active boolean not null default true);
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,url text not null,alt_text text,sort_order int not null default 0);
create table public.addresses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,recipient_name text not null,phone text not null,line1 text not null,city text not null,state text not null,postal_code text not null,country char(2) not null default 'IN');
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text unique not null,user_id uuid references auth.users(id),customer_name text not null,customer_email text not null,delivery_snapshot jsonb not null,status text not null default 'pending_payment',payment_status text not null default 'pending',payment_method text not null check(payment_method in ('razorpay','cod')),currency char(3) not null default 'INR',subtotal numeric(12,2) not null,discount_total numeric(12,2) not null default 0,tax_total numeric(12,2) not null default 0,shipping_total numeric(12,2) not null default 0,grand_total numeric(12,2) not null,created_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),product_id uuid references public.products(id),product_name_snapshot text not null,sku_snapshot text not null,unit_price numeric(12,2) not null,quantity int not null check(quantity>0),line_total numeric(12,2) not null);
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),provider text not null,provider_order_id text unique,provider_payment_id text unique,amount numeric(12,2) not null,currency char(3) not null default 'INR',status text not null default 'pending',verified_at timestamptz);
create table public.refunds(id uuid primary key default gen_random_uuid(),payment_id uuid not null references public.payments(id),amount numeric(12,2) not null check(amount>0),provider_refund_id text unique,status text not null,reason text);
create table public.inventory_batches(id uuid primary key default gen_random_uuid(),variant_id uuid not null references public.product_variants(id),batch_code text,received_quantity int not null check(received_quantity>=0),available_quantity int not null check(available_quantity>=0),expires_at date);
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),variant_id uuid not null references public.product_variants(id),movement_type text not null,quantity int not null,reason text,created_at timestamptz not null default now());
create table public.stock_reservations(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id),variant_id uuid not null references public.product_variants(id),quantity int not null check(quantity>0),expires_at timestamptz not null,released_at timestamptz);
create table public.shipments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),carrier text,tracking_number text,status text not null default 'pending');
create table public.return_requests(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),user_id uuid not null references auth.users(id),reason text not null,status text not null default 'requested',created_at timestamptz not null default now());
create table public.coupons(id uuid primary key default gen_random_uuid(),code text unique not null,discount_type text not null check(discount_type in ('fixed','percent')),discount_value numeric(12,2) not null,minimum_order numeric(12,2) not null default 0,active boolean not null default true);
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_user_id uuid references auth.users(id),action text not null,entity_type text not null,entity_id text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index products_category_status_idx on public.products(category_id,status);
create index orders_user_created_idx on public.orders(user_id,created_at desc);
alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.products enable row level security;alter table public.product_variants enable row level security;alter table public.addresses enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.payments enable row level security;
create policy "public categories" on public.categories for select using(active=true);
create policy "public active products" on public.products for select using(status='active');
create policy "public active variants" on public.product_variants for select using(active=true);
create policy "read own profile" on public.profiles for select using(auth.uid()=id);
create policy "update own profile" on public.profiles for update using(auth.uid()=id) with check(auth.uid()=id);
create policy "own addresses" on public.addresses for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own orders" on public.orders for select using(auth.uid()=user_id);
create policy "own order items" on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy "own payments" on public.payments for select using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
-- Keep order/payment/inventory/admin writes server-side; test every RLS policy before production.
